async function openInventory(){filaments=await api('/filaments');renderInventory();if(!$('#inventory-dialog').open)$('#inventory-dialog').showModal()}
function renderInventory(){const filter=$('#inventory-search').value.toLowerCase();const visible=filaments.filter(f=>(f.brand+' '+f.name+' '+f.material).toLowerCase().includes(filter));$('#inventory-list').innerHTML=visible.slice(0,150).map(f=>`<div class="inventory-item"><span class="swatch" style="background:${esc(f.hex)}"></span><span>${esc(f.brand)} / ${esc(f.name)}<small>${esc(f.material)} &middot; ${esc(f.hex)} &middot; ${f.measured?'gemessen':'ungemessen'}</small></span><label><input type="checkbox" data-inventory-owned="${esc(f.id)}" ${f.owned?'checked':''}>Vorrat</label><label><input type="checkbox" data-inventory-allowed="${esc(f.id)}" ${f.allowed!==false?'checked':''}>Erlaubt</label></div>`).join('')+(visible.length>150?`<p class="tiny">150 von ${visible.length} Eintraegen. Bitte Suche eingrenzen.</p>`:'');
 for(const prop of ['owned','allowed'])$$(`[data-inventory-${prop}]`).forEach(input=>input.onchange=safe(async()=>{const id=input.getAttribute('data-inventory-'+prop);const f=filaments.find(f=>f.id===id);f[prop]=input.checked;await api('/filaments',{method:'POST',json:f})}));
}
async function start(){setProjectLoading(true);try{try{viewer=new Viewer($('#viewer'),selectPart)}catch(e){$('#webgl-error').hidden=false;$('#webgl-error').textContent=e.message}
 config=await api('/config');filaments=await api('/filaments');const projects=await refreshProjects();const previous=new URLSearchParams(window.location.search).get('project')||localStorage.getItem('figuraforge-project');if(projects.length)await loadProject(projects.find(p=>p.id===previous)?.id||projects[0].id);else{const p=await api('/projects',{method:'POST',json:{title:'Meine erste Charakterfigur'}});await loadProject(p.id)}
}catch(error){setProjectLoading(false);throw error}}
$('#new-project').onclick=()=>{if(!loading)$('#new-dialog').showModal()};$('#new-form').onsubmit=safe(async e=>{e.preventDefault();if(loading)return;const p=await api('/projects',{method:'POST',json:{title:new FormData(e.target).get('title')}});$('#new-dialog').close();e.target.reset();await loadProject(p.id)});
$('#new-project-compact').onclick=()=>{if(!loading)$('#new-dialog').showModal()};$('#project-select').onchange=safe(e=>loadProject(e.target.value));
$$('[data-close]').forEach(b=>b.onclick=()=>{const dialog=b.closest('dialog');dialog.close();if(dialog.id==='inventory-dialog'&&stage==='plan'&&planEditor){planEditor.render();planEditor.updateView();}});
$$('[data-stage]').forEach(b=>b.onclick=safe(async()=>{await navigateStage(b.dataset.stage)}));
$$('[data-mode]').forEach(b=>b.onclick=()=>{$$('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));viewer?.setMode(b.dataset.mode);$('#explode-control').hidden=b.dataset.mode!=='explode';$('#plate-select').hidden=b.dataset.mode!=='plates'});
$('#explode-range').oninput=e=>{if(viewer){viewer.explode=Number(e.target.value)/100;viewer.draw()}};
$('#plate-select').onchange=e=>{if(viewer){viewer.plate=Number(e.target.value);viewer.reset()}};
$('#viewer-lighting').onclick=e=>{if(!viewer)return;viewer.lighting=!viewer.lighting;e.currentTarget.textContent=viewer.lighting?'Licht an':'Licht aus';e.currentTarget.setAttribute('aria-pressed',String(viewer.lighting));e.currentTarget.title=viewer.lighting?'Beleuchtung ausschalten, um die zugewiesenen Druckfarben ohne Vorschau-Schatten zu prüfen. Ändert keine Druckfarben.':'Beleuchtung einschalten, um die räumliche Form zu sehen. Ändert keine Druckfarben.';viewer.draw()};
$('#reset-view').onclick=()=>viewer?.reset();$('#screenshot').onclick=()=>viewer?.screenshot();$('#empty-demo')?.addEventListener('click',safe(loadDemo));$('#demo-load').onclick=safe(loadDemo);
$('#settings-open').onclick=safe(openKeys);$('#inventory-open').onclick=safe(openInventory);$('#inventory-search').oninput=renderInventory;
$('#catalog-sync').onclick=safe(async()=>{const b=$('#catalog-sync');b.disabled=true;try{const r=await api('/filaments/sync-spoolmandb',{method:'POST',json:{}});toast(`${r.imported} Katalogeintraege importiert.`);await openInventory()}finally{b.disabled=false}});
$('#catalog-file').onchange=safe(async e=>{const file=e.target.files[0];if(!file)return;const r=await api('/filaments/import',{method:'POST',json:{format:$('#catalog-format').value,data:JSON.parse(await file.text())}});toast(`${r.imported} Filamente importiert.`);await openInventory()});
$('#filament-form').onsubmit=safe(async e=>{e.preventDefault();const f=new FormData(e.target);await api('/filaments',{method:'POST',json:{id:'user-'+crypto.randomUUID(),brand:f.get('brand'),name:f.get('name'),material:f.get('material'),hex:f.get('hex'),owned:f.has('owned'),allowed:true,measured:false}});e.target.reset();await openInventory();toast('Filament gespeichert.')});
$('#cancel-job').onclick=safe(async()=>{const j=project.jobs.find(j=>['queued','running'].includes(j.status));if(j)await api('/jobs/'+j.id+'/cancel',{method:'POST',json:{}})});
$('#login-form').onsubmit=safe(async e=>{e.preventDefault();const r=await fetch('/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:new FormData(e.target).get('token')})});if(!r.ok)throw new Error('Ungueltiges Zugriffstoken');$('#login-dialog').close();e.target.reset();await start()});
$('#api-docs').href='/docs';
safe(start)();
